                            size: ButtonSize.icon,
                            semanticLabel: 'Close',
                            onPressed: () => Navigator.maybePop(context),
                            child: AshlarIcon(
                              AshlarIconsRoundedStroke.x,
                              color: c.mutedForeground,
                            ),
                          ),
                        ),
                    ],
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}
