                              borderRadius: BorderRadius.circular(3),
                            ),
                            child: FractionallySizedBox(
                              widthFactor: _fraction,
                              child: Container(
                                height: 6,
                                decoration: BoxDecoration(
                                  color: c.primary,
                                  borderRadius: BorderRadius.circular(3),
                                ),
                              ),
                            ),
                          ),
                        ),
                        Positioned(
                          left: _fraction * usable,
                          child: AnimatedContainer(
                            duration: t.duration,
                            width: thumb,
                            height: thumb,
                            decoration: BoxDecoration(
