    final groups = widget.groups ?? [widget.length];
    var start = 0;
    final rows = <Widget>[];
    for (final (g, size) in groups.indexed) {
      if (g > 0) {
        rows.add(
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 8),
            child: Container(width: 8, height: 2, color: c.mutedForeground),
          ),
